#[derive(Debug, Clone)]
struct OptionDef {
    key: String,
    full: String,
    abbr: Option<String>,
    flag: bool,
    list: bool,
    default: Option<Value>,
    default_help: Option<String>,
    choices: Option<Vec<Value>>,
