#[derive(Debug)]
pub struct ParseError {
    pub message: String,
    pub exit_code: i32,
}

impl std::fmt::Display for ParseError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}", self.message)
    }
}

fn is_option(value: &str) -> bool {
    value.starts_with('-') && value != "-" && value != "--"
}

fn default_extensions() -> String {
    // Matches @babel/core DEFAULT_EXTENSIONS + ts,tsx sorted
    "cjs,es,es6,js,jsx,mjs,ts,tsx".to_string()
}

