fn format_option(option: &OptionDef) -> String {
    let mut text = String::from("  ");
    if let Some(abbr) = &option.abbr {
        text.push_str(&format!("-{}, ", abbr));
    } else {
        text.push_str("    ");
    }
    if option.flag {
        text.push_str(&format!("--(no-){}", option.full));
    } else {
        text.push_str(&format!("--{}", option.full));
    }
    if let Some(choices) = &option.choices {
        let joined: Vec<String> = choices
            .iter()
            .map(|c| match c {
                Value::String(s) => s.clone(),
                Value::Number(n) => n.to_string(),
                other => other.to_string(),
            })
            .collect();
        text.push('=');
        text.push_str(&joined.join("|"));
    } else if let Some(metavar) = &option.metavar {
        text.push('=');
        text.push_str(metavar);
    }
    if option.list {
        text.push_str(" ...");
    }
    if option.default_help.is_some() || option.default.is_some() || option.help.is_some() {
        text.push_str("  ");
        if text.len() < 32 {
            text.push_str(&" ".repeat(32 - text.len()));
        }
        let text_length = text.len();
        if let Some(help) = &option.help {
            text.push_str(help);
        }
        if option.default_help.is_some() || option.default.is_some() {
            if option.help.is_some() {
                text.push('\n');
            }
            let default_str = if let Some(dh) = &option.default_help {
                dh.clone()
            } else if let Some(d) = &option.default {
                match d {
                    Value::String(s) => s.clone(),
                    Value::Bool(b) => b.to_string(),
                    Value::Number(n) => n.to_string(),
                    other => other.to_string(),
                }
            } else {
                String::new()
            };
            text.push_str(&format!(
                "{}(default: {})",
                " ".repeat(text_length),
                default_str
            ));
        }
    }
    text
}

pub fn get_help_text() -> String {
    let mut opts = build_option_defs();
    opts.sort_by_key(|o| o.display_index);
    let body = opts
        .iter()
        .map(format_option)
        .collect::<Vec<_>>()
        .join("\n");

    // Match JS trimLeft() on a template that starts with newline
    format!(
        r#"Usage: jscodeshift [OPTION]... PATH...
  or:  jscodeshift [OPTION]... -t TRANSFORM_PATH PATH...
  or:  jscodeshift [OPTION]... -t URL PATH...
  or:  jscodeshift [OPTION]... --stdin < file_list.txt

Apply transform logic in TRANSFORM_PATH (recursively) to every PATH.
If --stdin is set, each line of the standard input is used as a path.

Options:
"..." behind an option means that it can be supplied multiple times.
All options are also passed to the transformer, which means you can supply custom options that are not listed here.

{}"#,
        body
    )
}

fn version_text(package_root: &Path) -> String {
    // Prefer asking Node for accurate dependency versions (matches original)
    let script = r#"
const path = require('path');
const root = process.argv[1];
const pkg = require(path.join(root, 'package.json'));
function requirePackage(name) {
  try {
    const entry = require.resolve(name, { paths: [root] });
    let dir = path.dirname(entry);
    while (dir !== '/') {
      try {
        const p = require(path.join(dir, 'package.json'));
        if (p.name === name) return p;
      } catch (e) {}
      dir = path.dirname(dir);
    }
  } catch (e) {}
  return {};
}
function ver(name) {
  try {
    if (name === '@babel/core') return require(require.resolve('@babel/core', { paths: [root] })).version;
  } catch (e) {}
  return requirePackage(name).version || '';
}
process.stdout.write([
  'jscodeshift: ' + pkg.version,
  ' - babel: ' + ver('@babel/core'),
  ' - babylon: ' + ver('@babel/parser'),
  ' - flow: ' + ver('flow-parser'),
  ' - recast: ' + ver('recast') + '\n',
].join('\n'));
"#;
    let root_str = package_root.to_string_lossy().to_string();
    match std::process::Command::new("node")
        .arg("-e")
        .arg(script)
        .arg(&root_str)
        .output()
    {
        Ok(out) if out.status.success() => String::from_utf8_lossy(&out.stdout).to_string(),
        _ => {
            let ver = env::var("JSCODESHIFT_VERSION").unwrap_or_else(|_| "17.4.0".into());
            format!(
                "jscodeshift: {}\n - babel: \n - babylon: \n - flow: \n - recast: \n",
                ver
            )
        }
    }
}

fn process_value(process: &Option<String>, value: &str) -> Result<Value, ParseError> {
    match process.as_deref() {
        Some("number") => {
            let n: serde_json::Number = value
                .parse::<f64>()
                .ok()
                .and_then(serde_json::Number::from_f64)
                .or_else(|| value.parse::<i64>().ok().map(Into::into))
                .unwrap_or_else(|| serde_json::Number::from(0));
            // JS Number("1") => 1; Number() on non-numeric => NaN
            if let Ok(i) = value.parse::<i64>() {
                Ok(Value::Number(i.into()))
            } else if let Ok(f) = value.parse::<f64>() {
                Ok(Value::Number(
                    serde_json::Number::from_f64(f).unwrap_or_else(|| 0.into()),
                ))
            } else {
                // Match JS Number("x") => NaN which becomes null-ish; store as null
                let _ = n;
                Ok(Value::Null)
            }
        }
        Some("parser_config") => {
            let content = fs::read_to_string(value).map_err(|e| ParseError {
                message: format!("{}", e),
                exit_code: 1,
            })?;
            serde_json::from_str(&content).map_err(|e| ParseError {
                message: format!("{}", e),
                exit_code: 1,
            })
        }
        _ => {
            // Try JSON parse like nomnom compatibility for unknown options;
            // for known string options just return string
            Ok(Value::String(value.to_string()))
        }
    }
}

fn try_json_or_string(value: &str) -> Value {
    match serde_json::from_str::<Value>(value) {
        Ok(v) => v,
        Err(_) => Value::String(value.to_string()),
    }
}

pub fn parse(args: &[String], package_root: &Path) -> Result<ParsedArgs, ParseError> {
    let defs = build_option_defs();
    let mut by_flag: HashMap<String, OptionDef> = HashMap::new();
    for d in &defs {
        by_flag.insert(format!("--{}", d.full), d.clone());
        if let Some(abbr) = &d.abbr {
            by_flag.insert(format!("-{}", abbr), d.clone());
        }
        if d.flag {
            by_flag.insert(format!("--no-{}", d.full), d.clone());
        }
    }

    let mut parsed: HashMap<String, Value> = HashMap::new();
    for d in &defs {
        if let Some(default) = &d.default {
            parsed.insert(d.key.clone(), default.clone());
        } else if d.list {
            parsed.insert(d.key.clone(), Value::Array(vec![]));
        }
    }

    let mut positional: Vec<Value> = Vec::new();
    let missing_value = Value::String("__MISSING__".into());
    let mut i = 0usize;
    while i < args.len() {
        let arg = &args[i];
        if is_option(arg) {
            let mut option_name = arg.clone();
            let mut value: Option<String> = None;
            if let Some(idx) = arg.find('=') {
                option_name = arg[..idx].to_string();
                value = Some(arg[idx + 1..].to_string());
            }

            let known = by_flag.get(&option_name).cloned();
            let option = if let Some(opt) = known {
                opt
            } else {
                // Unknown options are "passed along"
                let real_option_name = option_name
                    .trim_start_matches('-')
                    .trim_start_matches("no-")
                    .to_string();
                // Handle --no-foo for unknown
                let real_option_name = if option_name.starts_with("--no-") {
                    option_name[5..].to_string()
                } else {
                    real_option_name
                        .trim_start_matches('-')
                        .to_string()
                };

                let is_list = parsed.contains_key(&real_option_name)
                    && parsed.get(&real_option_name) != Some(&Value::Bool(true));

                if is_list {
                    let current = parsed.get(&real_option_name).cloned();
                    if let Some(cur) = current {
                        if !cur.is_array() {
                            if cur == Value::Bool(true) {
                                parsed.insert(real_option_name.clone(), Value::Array(vec![]));
                            } else {
                                parsed.insert(
                                    real_option_name.clone(),
                                    Value::Array(vec![cur]),
                                );
                            }
                        }
                    }
                }

                let next_is_option = args.get(i + 1).map(|s| is_option(s)).unwrap_or(true);
                let flag = !parsed.contains_key(&real_option_name)
                    && value.is_none()
                    && next_is_option;

                OptionDef {
                    key: real_option_name.clone(),
                    full: real_option_name,
                    abbr: None,
                    flag,
                    list: is_list,
                    default: None,
                    default_help: None,
                    choices: None,
                    help: None,
                    metavar: None,
                    display_index: 999,
                    process: Some("json_or_string".into()),
                }
            };

            // Callbacks
            if option.process.as_deref() == Some("callback_help") {
                return Err(ParseError {
                    message: get_help_text(),
                    exit_code: 0,
                });
            }
            if option.process.as_deref() == Some("callback_version") {
                return Err(ParseError {
                    message: version_text(package_root),
                    exit_code: 0,
                });
            }

            if option.flag {
                let v = if option_name.starts_with("--no-") {
                    false
                } else if let Some(ref val) = value {
                    val == "1"
                } else {
                    true
                };
                parsed.insert(option.key.clone(), Value::Bool(v));
            } else {
                if value.is_none() && i + 1 < args.len() && !is_option(&args[i + 1]) {
                    value = Some(args[i + 1].clone());
                    i += 1;
                }
                if let Some(val) = value {
                    let processed = if option.process.as_deref() == Some("json_or_string") {
                        try_json_or_string(&val)
                    } else if option.process.as_deref() == Some("number") {
                        process_value(&option.process, &val)?
                    } else if option.process.as_deref() == Some("parser_config") {
                        process_value(&option.process, &val)?
                    } else {
                        Value::String(val)
                    };
                    if option.list {
                        let arr = parsed
                            .entry(option.key.clone())
                            .or_insert_with(|| Value::Array(vec![]));
                        if let Value::Array(a) = arr {
                            a.push(processed);
                        }
                    } else {
                        parsed.insert(option.key.clone(), processed);
                    }
                } else {
                    parsed.insert(option.key.clone(), missing_value.clone());
                }
            }
        } else {
            // positional: number if all digits
            if arg.chars().all(|c| c.is_ascii_digit()) && !arg.is_empty() {
                if let Ok(n) = arg.parse::<i64>() {
                    positional.push(Value::Number(n.into()));
                } else {
                    positional.push(Value::String(arg.clone()));
                }
            } else {
                positional.push(Value::String(arg.clone()));
            }
        }
        i += 1;
    }

    // Missing values
    for (k, v) in &parsed {
        if v == &missing_value {
            let full = defs
                .iter()
                .find(|d| &d.key == k)
                .map(|d| d.full.clone())
                .unwrap_or_else(|| k.clone());
            return Err(ParseError {
                message: format!(
                    "Missing value: --{} requires a value\n\n---\n\n{}",
                    full,
                    get_help_text()
                ),
                exit_code: 1,
            });
        }
    }

    // Validate choices
    let mut errors = Vec::new();
    for d in &defs {
        if let Some(choices) = &d.choices {
            if let Some(val) = parsed.get(&d.key) {
                // Coerce number comparison: verbose may be number
                let ok = choices.iter().any(|c| values_equal(c, val));
                if !ok {
                    let choice_str: Vec<String> = choices
                        .iter()
                        .map(|c| match c {
                            Value::String(s) => s.clone(),
                            Value::Number(n) => n.to_string(),
                            other => other.to_string(),
                        })
                        .collect();
                    errors.push(format!(
                        "Error: --{} must be one of the values {}",
                        d.full,
                        choice_str.join(",")
                    ));
                }
            }
        }
    }
    if !errors.is_empty() {
        return Err(ParseError {
            message: format!("{}\n\n---\n\n{}", errors.join("\n"), get_help_text()),
            exit_code: 1,
        });
    }

    Ok(ParsedArgs {
        options: parsed,
        positional_arguments: positional,
    })
}

fn values_equal(a: &Value, b: &Value) -> bool {
    if a == b {
        return true;
    }
    // 0 == "0" loose? JS choices.includes uses strict equality
    // Number choices vs Number values
    match (a, b) {
        (Value::Number(n1), Value::Number(n2)) => n1.as_f64() == n2.as_f64(),
        _ => false,
    }
}

