{"command":"create","path":"/workspace/codebase/rust/src/ignore.rs","file_text":"//! Ignore pattern handling compatible with jscodeshift ignoreFiles.js
use globset::{Glob, GlobSet, GlobSetBuilder};
use std::fs;
use std::path::Path;
use std::sync::Mutex;

/// Shared ignore state (mirrors module-level matchers array in JS)
pub struct IgnoreState {
    patterns: Vec<String>,
    globset: Option<GlobSet>,
}

impl IgnoreState {
    pub fn new() -> Self {
        Self {
            patterns: Vec::new(),
            globset: None,
        }
    }

    fn rebuild(&mut self) {
        let mut builder = GlobSetBuilder::new();
        for p in &self.patterns {
            // picomatch with dot:true — match hidden files
            if let Ok(glob) = Glob::new(p) {
                builder.add(glob);
            }
            // Also try without leading **/
        }
        self.globset = builder.build().ok();
    }

    /// Add a single gitignore-style / glob pattern
    pub fn add_ignore_pattern(&mut self, val: &str) {
        if val.is_empty() || val.starts_with('#') {
            return;
        }
        let pattern = val.to_string();
        if !pattern.contains('/') {
            self.patterns.push(format!("**/{}", pattern));
        } else if pattern.ends_with('/') {
            self.patterns.push(format!("**/{}**", pattern));
            self.patterns.push(format!("{}**", pattern));
        }
        self.patterns.push(pattern);
        self.rebuild();
    }

    pub fn add_from_input(&mut self, input: &[String]) {
        for p in input {
            self.add_ignore_pattern(p);
        }
    }

    pub fn add_from_file(&mut self, files: &[String]) {
        for config in files {
            let path = Path::new(config);
            if let Ok(meta) = fs::metadata(path) {
                if meta.is_file() {
                    if let Ok(content) = fs::read_to_string(path) {
                        for line in content.split('\n') {
                            let line = line.trim_end_matches('\r');
                            self.add_ignore_pattern(line);
                        }
                    }
                }
            }
        }
    }

    pub fn should_ignore(&self, path: &str) -> bool {
        if self.patterns.is_empty() {
            return false;
        }
        let set = match &self.globset {
            Some(s) => s,
            None => return false,
        };

        // Match original path
        if set.is_match(path) {
            return true;
        }

        // Strip leading ./ or ../ traversal prefixes (issue #556)
        let normalized = strip_traversal_prefix(path);
        if normalized != path && set.is_match(normalized) {
            return true;
        }
        false
    }
}

fn strip_traversal_prefix(path: &str) -> &str {
    let mut s = path;
    loop {
        if let Some(rest) = s.strip_prefix("./") {
            s = rest;
            continue;
        }
        if let Some(rest) = s.strip_prefix(".\\") {
            s = rest;
            continue;
        }
        if let Some(rest) = s.strip_prefix("../") {
            s = rest;
            continue;
        }
        if let Some(rest) = s.strip_prefix("..\\") {
            s = rest;
            continue;
        }
        break;
    }
    s
}

/// Global ignore state used by the runner
pub static IGNORES: once_cell_mutex::OnceMutex<IgnoreState> =
    once_cell_mutex::OnceMutex::new();

// Simple once-mutex without extra crate dependency
mod once_cell_mutex {
    use super::IgnoreState;
    use std::sync::{Mutex, OnceLock};

    pub struct OnceMutex {
        inner: OnceLock<Mutex<IgnoreState>>,
    }

    impl OnceMutex {
        pub const fn new() -> Self {
            Self {
                inner: OnceLock::new(),
            }
        }

        pub fn with_mut<F, R>(&self, f: F) -> R
        where
            F: FnOnce(&mut IgnoreState) -> R,
        {
            let mutex = self.inner.get_or_init(|| Mutex::new(IgnoreState::new()));
            let mut guard = mutex.lock().unwrap();
            f(&mut guard)
        }

        pub fn with<F, R>(&self, f: F) -> R
        where
            F: FnOnce(&IgnoreState) -> R,
        {
            let mutex = self.inner.get_or_init(|| Mutex::new(IgnoreState::new()));
            let guard = mutex.lock().unwrap();
            f(&guard)
        }
    }
}

pub fn add(patterns: &[String]) {
    IGNORES.with_mut(|s| s.add_from_input(patterns));
}

pub fn add_from_file(files: &[String]) {
    IGNORES.with_mut(|s| s.add_from_file(files));
}

pub fn should_ignore(path: &str) -> bool {
    IGNORES.with(|s| s.should_ignore(path))
}

pub fn reset() {
    IGNORES.with_mut(|s| {
        s.patterns.clear();
        s.globset = None;
    });
}
"}

{"command":"create","path":"/workspace/codebase/rust/src/runner.rs","file_text":"//! Runner: file discovery, worker orchestration, stats — port of Runner.js
use crate::ignore;
use colored::Colorize;
use serde_json::{json, Value};
use std::collections::HashMap;
use std::fs;
use std::io::{self, BufRead, BufReader, Write};
use std::path::{Path, PathBuf};
use std::process::{Child, Command, Stdio};
use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::{Arc, Mutex};
use std::thread;
use std::time::Instant;

const CHUNK_SIZE: usize = 50;

fn available_cpus() -> usize {
    std::cmp::max(num_cpus::get().saturating_sub(1), 1)
}

fn line_break(s: &str) -> String {
    if s.ends_with('\n') {
        s.to_string()
    } else {
        format!("{}\n", s)
    }
}

struct Logger;

impl Logger {
    fn ok(msg: &str, verbose: i64) {
        if verbose >= 2 {
            print!("{}{}", " OKK ".on_green().white(), msg);
            let _ = io::stdout().flush();
        }
    }
    fn nochange(msg: &str, verbose: i64) {
        if verbose >= 1 {
            print!("{}{}", " NOC ".on_yellow().white(), msg);
            let _ = io::stdout().flush();
        }
    }
    fn skip(msg: &str, verbose: i64) {
        if verbose >= 1 {
            print!("{}{}", " SKIP ".on_yellow().white(), msg);
            let _ = io::stdout().flush();
        }
    }
    fn error(msg: &str, verbose: i64) {
        if verbose >= 0 {
            print!("{}{}", " ERR ".on_red().white(), msg);
            let _ = io::stdout().flush();
        }
    }
    fn report(file: &str, msg: &str) {
        print!(
            "{}",
            line_break(&format!("{}{} {}", " REP ".on_blue().white(), file, msg))
        );
        let _ = io::stdout().flush();
    }
}

fn show_file_stats(error: usize, nochange: usize, skip: usize, ok: usize) {
    print!("Results: \n");
    print!("{}", format!("{} errors\n", error).red());
    print!("{}", format!("{} unmodified\n", nochange).yellow());
    print!("{}", format!("{} skipped\n", skip).yellow());
    print!("{}", format!("{} ok\n", ok).green());
    let _ = io::stdout().flush();
}

fn show_stats(stats: &HashMap<String, i64>) {
    let mut names: Vec<_> = stats.keys().cloned().collect();
    names.sort();
    if !names.is_empty() {
        print!("{}", "Stats: \n".blue());
    }
    for name in names {
        println!("{}: {}", name, stats[&name]);
    }
}

fn collect_dir_files(dir: &Path, filter: &dyn Fn(&str) -> bool) -> Vec<String> {
    let mut files = Vec::new();
    let mut stack = vec![dir.to_path_buf()];
    while let Some(current) = stack.pop() {
        let entries = match fs::read_dir(&current) {
            Ok(e) => e,
            Err(_) => continue,
        };
        for entry in entries.flatten() {
            let name = entry.path();
            let name_str = name.to_string_lossy().to_string();
            // Match JS path.join which may not have trailing slash quirks
            let meta = match fs::symlink_metadata(&name) {
                Ok(m) => m,
                Err(_) => {
                    // Skipping path that does not exist
                    print!("Skipping path \"{}\" which does not exist.\n", name_str);
                    continue;
                }
            };
            if ignore::should_ignore(&name_str) {
                continue;
            }
            if meta.is_dir() {
                // JS uses name + '/' for recursion but path.join for files
                stack.push(name);
            } else if meta.is_file() || meta.file_type().is_symlink() {
                // Follow the JS: after readdir+stat, push files. Symlinks to files?
                // JS fs.stat follows symlinks. Use fs::metadata for follow.
                match fs::metadata(&name) {
                    Ok(m) if m.is_dir() => stack.push(name),
                    Ok(_) => {
                        if filter(&name_str) {
                            files.push(name_str);
                        }
                    }
                    Err(_) => {
                        print!("Skipping path \"{}\" which does not exist.\n", name_str);
                    }
                }
            }
        }
    }
    files
}

fn get_all_files(paths: &[String], filter: &dyn Fn(&str) -> bool) -> Vec<String> {
    let mut result = Vec::new();
    for file in paths {
        if file.is_empty() {
            continue;
        }
        match fs::symlink_metadata(file) {
            Err(_) => {
                eprint!("Skipping path {} which does not exist. \n", file);
            }
            Ok(stat) => {
                if stat.is_dir() {
                    // JS uses fs.lstat then if directory dirFiles with filter
                    // For directories, JS calls fs.stat (follow) via the flow in dirFiles
                    let mut dir_path = PathBuf::from(file);
                    // Keep as given
                    let list = collect_dir_files(&dir_path, filter);
                    result.extend(list);
                } else if !filter(file) || ignore::should_ignore(file) {
                    // ignoring
                } else {
                    result.push(file.clone());
                }
            }
        }
    }
    result
}

fn value_as_bool(v: &Value) -> bool {
    match v {
        Value::Bool(b) => *b,
        Value::String(s) => s == "true" || s == "1",
        Value::Number(n) => n.as_f64().unwrap_or(0.0) != 0.0,
        _ => false,
    }
}

fn value_as_i64(v: &Value) -> Option<i64> {
    match v {
        Value::Number(n) => n.as_i64().or_else(|| n.as_f64().map(|f| f as i64)),
        Value::String(s) => s.parse().ok(),
        _ => None,
    }
}

fn value_as_string_list(v: Option<&Value>) -> Vec<String> {
    match v {
        Some(Value::Array(arr)) => arr
            .iter()
            .filter_map(|x| match x {
                Value::String(s) => Some(s.clone()),
                other => Some(other.to_string()),
            })
            .collect(),
        Some(Value::String(s)) => vec![s.clone()],
        _ => vec![],
    }
}

fn find_bridge(package_root: &Path) -> PathBuf {
    let candidates = [
        package_root.join("bridge/transform-host.js"),
        package_root.join("dist/bridge/transform-host.js"),
    ];
    for c in &candidates {
        if c.exists() {
            return c.clone();
        }
    }
    // fallback relative to executable
    if let Ok(exe) = std::env::current_exe() {
        if let Some(dir) = exe.parent() {
            let p = dir.join("../bridge/transform-host.js");
            if p.exists() {
                return p;
            }
            let p = dir.join("bridge/transform-host.js");
            if p.exists() {
                return p;
            }
        }
    }
    package_root.join("bridge/transform-host.js")
}

fn download_transform(url: &str) -> Result<PathBuf, String> {
    let body = ureq::get(url)
        .call()
        .map_err(|e| format!("{}", e))?
        .into_string()
        .map_err(|e| format!("{}", e))?;

    let ext = Path::new(url)
        .extension()
        .and_then(|e| e.to_str())
        .unwrap_or("js");
    let mut tmp = tempfile::Builder::new()
        .prefix("jscodeshift")
        .suffix(&format!(".{}", ext))
        .tempfile()
        .map_err(|e| format!("{}", e))?;
    tmp.write_all(body.as_bytes())
        .map_err(|e| format!("{}", e))?;
    // Persist so worker can read it for the process lifetime
    let path = tmp.into_temp_path();
    let kept = path.keep().map_err(|e| format!("{}", e))?;
    Ok(kept)
}

/// Options subset forwarded to workers (full options map is forwarded as JSON)
pub struct RunResult {
    pub error: usize,
    pub ok: usize,
    pub nochange: usize,
    pub skip: usize,
    pub stats: HashMap<String, i64>,
    pub time_elapsed: f64,
}

pub fn run(
    transform_file: &str,
    paths: Vec<String>,
    options: &HashMap<String, Value>,
    package_root: &Path,
) -> Option<RunResult> {
    ignore::reset();

    let cpus = options
        .get("cpus")
        .and_then(value_as_i64)
        .map(|n| std::cmp::min(available_cpus(), n as usize))
        .unwrap_or_else(available_cpus);

    let extensions: Option<Vec<String>> = options
        .get("extensions")
        .and_then(|v| v.as_str())
        .map(|s| {
            s.split(',')
                .map(|ext| format!(".{}", ext.trim()))
                .collect()
        });

    // ignore patterns
    let ignore_pattern = value_as_string_list(options.get("ignorePattern"));
    let ignore_config = value_as_string_list(options.get("ignoreConfig"));
    // ignoreSet is not a CLI option but may exist
    let ignore_set = value_as_string_list(options.get("ignoreSet"));
    ignore::add(&ignore_set);
    ignore::add(&ignore_pattern);
    ignore::add_from_file(&ignore_config);

    if options.get("gitignore").map(value_as_bool).unwrap_or(false) {
        let cwd = std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."));
        let gitignore = cwd.join(".gitignore");
        ignore::add_from_file(&[gitignore.to_string_lossy().to_string()]);
    }

    let transform_path = if transform_file.starts_with("http://")
        || transform_file.starts_with("https://")
    {
        match download_transform(transform_file) {
            Ok(p) => p,
            Err(e) => {
                eprint!("Error downloading transform: {}\n", e);
                return None;
            }
        }
    } else {
        let p = PathBuf::from(transform_file);
        if !p.exists() {
            eprint!(
                "{} Transform file {} does not exist \n",
                "ERROR".on_red().white(),
                transform_file
            );
            return None;
        }
        p
    };

    let filter = |name: &str| {
        if let Some(ref exts) = extensions {
            let ext = Path::new(name)
                .extension()
                .and_then(|e| e.to_str())
                .map(|e| format!(".{}", e))
                .unwrap_or_default();
            exts.iter().any(|e| e == &ext)
        } else {
            true
        }
    };

    let files = get_all_files(&paths, &filter);
    let num_files = files.len();
    let silent = options.get("silent").map(value_as_bool).unwrap_or(false);
    let run_in_band = options
        .get("runInBand")
        .map(value_as_bool)
        .unwrap_or(false);
    let dry = options.get("dry").map(value_as_bool).unwrap_or(false);
    let verbose = options
        .get("verbose")
        .and_then(value_as_i64)
        .unwrap_or(0);
    let fail_on_error = options
        .get("failOnError")
        .map(value_as_bool)
        .unwrap_or(false);
    let babel = options.get("babel").map(value_as_bool).unwrap_or(true);

    if num_files == 0 {
        print!("No files selected, nothing to do. \n");
        return Some(RunResult {
            error: 0,
            ok: 0,
            nochange: 0,
            skip: 0,
            stats: HashMap::new(),
            time_elapsed: 0.0,
        });
    }

    let processes = if run_in_band {
        1
    } else {
        std::cmp::min(num_files, cpus)
    };
    let chunk_size = if processes > 1 {
        std::cmp::min((num_files + processes - 1) / processes, CHUNK_SIZE)
    } else {
        num_files
    };

    if !silent {
        print!("Processing {} files... \n", files.len());
        if !run_in_band {
            print!("Spawning {} workers...\n", processes);
        }
        if dry {
            print!(
                "{}",
                "Running in dry mode, no files will be written! \n".green()
            );
        }
        let _ = io::stdout().flush();
    }

    let start = Instant::now();
    let file_index = Arc::new(AtomicUsize::new(0));
    let counters = Arc::new(Mutex::new(FileCounters::default()));
    let stats_counter = Arc::new(Mutex::new(HashMap::<String, i64>::new()));

    let bridge = find_bridge(package_root);
    let babel_arg = if babel { "babel" } else { "no-babel" };
    let transform_str = transform_path.to_string_lossy().to_string();
    let options_json = serde_json::to_string(options).unwrap_or_else(|_| "{}".into());

    let files = Arc::new(files);

    let mut handles = Vec::new();

    for worker_id in 0..processes {
        let files = Arc::clone(&files);
        let file_index = Arc::clone(&file_index);
        let counters = Arc::clone(&counters);
        let stats_counter = Arc::clone(&stats_counter);
        let bridge = bridge.clone();
        let transform_str = transform_str.clone();
        let babel_arg = babel_arg.to_string();
        let options_json = options_json.clone();
        let silent = silent;
        let run_in_band = run_in_band;
        let verbose = verbose;
        let num_files = num_files;
        let chunk_size = chunk_size;

        let handle = thread::spawn(move || {
            worker_loop(
                worker_id,
                &bridge,
                &transform_str,
                &babel_arg,
                &options_json,
                files,
                file_index,
                counters,
                stats_counter,
                silent,
                run_in_band,
                verbose,
                num_files,
                chunk_size,
            );
        });
        handles.push(handle);
    }

    for h in handles {
        let _ = h.join();
    }

    let elapsed = start.elapsed().as_secs_f64();
    let time_elapsed = (elapsed * 1000.0).round() / 1000.0; // ~toFixed(3) rough

    // Format like JS toFixed(3)
    let time_str = format!("{:.3}", elapsed);

    let counters = counters.lock().unwrap().clone();
    let stats = stats_counter.lock().unwrap().clone();

    if !silent {
        print!("All done. \n");
        show_file_stats(
            counters.error,
            counters.nochange,
            counters.skip,
            counters.ok,
        );
        show_stats(&stats);
        print!("Time elapsed: {}seconds \n", time_str);
        let _ = io::stdout().flush();

        if fail_on_error && counters.error > 0 {
            std::process::exit(1);
        }
    }

    Some(RunResult {
        error: counters.error,
        ok: counters.ok,
        nochange: counters.nochange,
        skip: counters.skip,
        stats,
        time_elapsed: elapsed,
    })
}

#[derive(Default, Clone)]
struct FileCounters {
    error: usize,
    ok: usize,
    nochange: usize,
    skip: usize,
}

fn next_chunk(
    files: &[String],
    file_index: &AtomicUsize,
    chunk_size: usize,
    silent: bool,
    run_in_band: bool,
) -> Vec<String> {
    let num_files = files.len();
    let index = file_index.fetch_add(chunk_size, Ordering::SeqCst);
    if index >= num_files {
        return vec![];
    }
    let end = std::cmp::min(index + chunk_size, num_files);
    if !silent && !run_in_band && index < num_files {
        print!(
            "Sending {} files to free worker...\n",
            end - index
        );
        let _ = io::stdout().flush();
    }
    files[index..end].to_vec()
}

fn worker_loop(
    _worker_id: usize,
    bridge: &Path,
    transform: &str,
    babel_arg: &str,
    options_json: &str,
    files: Arc<Vec<String>>,
    file_index: Arc<AtomicUsize>,
    counters: Arc<Mutex<FileCounters>>,
    stats_counter: Arc<Mutex<HashMap<String, i64>>>,
    silent: bool,
    run_in_band: bool,
    verbose: i64,
    _num_files: usize,
    chunk_size: usize,
) {
    let mut child = match spawn_worker(bridge, transform, babel_arg) {
        Ok(c) => c,
        Err(e) => {
            eprint!("Failed to spawn worker: {}\n", e);
            return;
        }
    };

    let mut stdin = child.stdin.take().expect("stdin");
    let stdout = child.stdout.take().expect("stdout");
    let mut reader = BufReader::new(stdout);

    // Send initial chunk
    let chunk = next_chunk(&files, &file_index, chunk_size, silent, run_in_band);
    if let Err(e) = send_message(&mut stdin, &chunk, options_json) {
        eprint!("Failed to send to worker: {}\n", e);
        let _ = child.kill();
        return;
    }

    let mut line = String::new();
    loop {
        line.clear();
        match reader.read_line(&mut line) {
            Ok(0) => break, // EOF
            Ok(_) => {
                let trimmed = line.trim();
                if trimmed.is_empty() {
                    continue;
                }
                let msg: Value = match serde_json::from_str(trimmed) {
                    Ok(v) => v,
                    Err(_) => continue,
                };
                let action = msg.get("action").and_then(|a| a.as_str()).unwrap_or("");
                match action {
                    "status" => {
                        let status = msg
                            .get("status")
                            .and_then(|s| s.as_str())
                            .unwrap_or("error");
                        let m = msg.get("msg").and_then(|s| s.as_str()).unwrap_or("");
                        {
                            let mut c = counters.lock().unwrap();
                            match status {
                                "error" => c.error += 1,
                                "ok" => c.ok += 1,
                                "nochange" => c.nochange += 1,
                                "skip" => c.skip += 1,
                                _ => {}
                            }
                        }
                        let msg_lb = line_break(m);
                        match status {
                            "ok" => Logger::ok(&msg_lb, verbose),
                            "nochange" => Logger::nochange(&msg_lb, verbose),
                            "skip" => Logger::skip(&msg_lb, verbose),
                            "error" => Logger::error(&msg_lb, verbose),
                            _ => {}
                        }
                    }
                    "update" => {
                        let name = msg
                            .get("name")
                            .and_then(|s| s.as_str())
                            .unwrap_or("")
                            .to_string();
                        let quantity = msg
                            .get("quantity")
                            .and_then(|q| q.as_i64())
                            .unwrap_or(1);
                        let mut s = stats_counter.lock().unwrap();
                        *s.entry(name).or_insert(0) += quantity;
                    }
                    "report" => {
                        let file = msg.get("file").and_then(|s| s.as_str()).unwrap_or("");
                        let m = msg.get("msg").and_then(|s| s.as_str()).unwrap_or("");
                        Logger::report(file, m);
                    }
                    "free" => {
                        let chunk =
                            next_chunk(&files, &file_index, chunk_size, silent, run_in_band);
                        if chunk.is_empty() {
                            // Send empty to signal finish
                            if send_message(&mut stdin, &[], options_json).is_err() {
                                break;
                            }
                            // Worker will exit after empty files
                        } else if send_message(&mut stdin, &chunk, options_json).is_err() {
                            break;
                        }
                    }
                    "done" => {
                        break;
                    }
                    _ => {}
                }
            }
            Err(_) => break,
        }
    }

    let _ = child.wait();
}

fn spawn_worker(bridge: &Path, transform: &str, babel_arg: &str) -> io::Result<Child> {
    Command::new("node")
        .arg(bridge)
        .arg(transform)
        .arg(babel_arg)
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::inherit())
        .spawn()
}

fn send_message(stdin: &mut impl Write, files: &[String], options_json: &str) -> io::Result<()> {
