{"command":"create","path":"/workspace/codebase/rust/src/main.rs","file_text":"//! jscodeshift CLI — Rust port of bin/jscodeshift.js
mod args;
mod ignore;
mod runner;

use serde_json::Value;
use std::env;
use std::io::{self, Read};
use std::path::{Path, PathBuf};
use std::process;

fn find_package_root() -> PathBuf {
    // 1) env override
    if let Ok(p) = env::var("JSCODESHIFT_ROOT") {
        return PathBuf::from(p);
    }
    // 2) relative to executable: <root>/bin/jscodeshift or <root>/target/.../jscodeshift
    if let Ok(exe) = env::current_exe() {
        // Check parent directories for package.json with name jscodeshift
        let mut dir = exe.parent().map(|p| p.to_path_buf());
        for _ in 0..6 {
            if let Some(ref d) = dir {
                let pkg = d.join("package.json");
                if pkg.exists() {
                    if let Ok(content) = std::fs::read_to_string(&pkg) {
                        if content.contains("\"name\": \"jscodeshift\"")
                            || content.contains("\"name\":\"jscodeshift\"")
                        {
                            return d.clone();
                        }
                    }
                }
                dir = d.parent().map(|p| p.to_path_buf());
            }
        }
    }
    // 3) cwd
    if let Ok(cwd) = env::current_dir() {
        if cwd.join("package.json").exists() {
            return cwd;
        }
        // cwd/codebase
        if cwd.join("codebase/package.json").exists() {
            return cwd.join("codebase");
        }
    }
    env::current_dir().unwrap_or_else(|_| PathBuf::from("."))
}

fn resolve_transform(transform: &str) -> String {
    if transform.starts_with("http://") || transform.starts_with("https://") {
        return transform.to_string();
    }
    // path.resolve equivalent
    let p = Path::new(transform);
    if p.is_absolute() {
        transform.to_string()
    } else {
        env::current_dir()
            .unwrap_or_else(|_| PathBuf::from("."))
            .join(p)
            .to_string_lossy()
            .to_string()
    }
}

fn main() {
    let package_root = find_package_root();
    let raw_args: Vec<String> = env::args().skip(1).collect();

    let parsed = match args::parse(&raw_args, &package_root) {
        Ok(p) => p,
        Err(e) => {
            if e.exit_code != 0 {
                eprint!("{}", e.message);
            } else {
                print!("{}", e.message);
            }
            process::exit(e.exit_code);
        }
    };

    let stdin_flag = parsed
        .options
        .get("stdin")
        .and_then(|v| v.as_bool())
        .unwrap_or(false);

    if parsed.positional_arguments.is_empty() && !stdin_flag {
        eprint!(
            "Error: You have to provide at least one file/directory to transform.\n\n---\n\n{}",
            args::get_help_text()
        );
        process::exit(1);
    }

    let transform = parsed
        .options
        .get("transform")
        .and_then(|v| v.as_str())
        .unwrap_or("./transform.js");
    let transform = resolve_transform(transform);

    let paths: Vec<String> = if stdin_flag {
        let mut buffer = String::new();
        let _ = io::stdin().read_to_string(&mut buffer);
        buffer
            .split('\n')
            .map(|s| s.to_string())
            .collect()
    } else {
        parsed
            .positional_arguments
            .iter()
            .map(|v| match v {
                Value::String(s) => s.clone(),
                Value::Number(n) => n.to_string(),
                other => other.to_string(),
            })
            .collect()
    };

    runner::run(&transform, paths, &parsed.options, &package_root);
}
"}

{"command":"create","path":"/workspace/codebase/bridge/transform-host.js","file_text":"#!/usr/bin/env node
/**
 * Transform host bridge — Node worker invoked by the Rust runner.
 * Ports src/Worker.js communication from process IPC to stdin/stdout JSON lines,
 * while preserving transform loading, babel-register, and file-writing behavior.
 */
'use strict';

const path = require('path');
const readline = require('readline');

const async = require('neo-async');
const fs = require('graceful-fs');
const writeFileAtomic = require('write-file-atomic');
const { DEFAULT_EXTENSIONS } = require('@babel/core');

// Resolve package root (parent of bridge/)
const PACKAGE_ROOT = path.resolve(__dirname, '..');

const getParser = require(path.join(PACKAGE_ROOT, 'src', 'getParser'));
const jscodeshift = require(path.join(PACKAGE_ROOT, 'src', 'core'));

let presetEnv;
try {
  presetEnv = require('@babel/preset-env');
} catch (_) {}

let transform;
let parserFromTransform;

function notify(data) {
  // One JSON object per line on stdout for the Rust runner
  process.stdout.write(JSON.stringify(data) + '\n');
}

function finish() {
  notify({ action: 'done' });
  // Allow the write to flush then exit
  setImmediate(() => process.exit(0));
}

function prepareJscodeshift(options) {
  const parser = parserFromTransform ||
    getParser(options.parser, options.parserConfig);
  return jscodeshift.withParser(parser);
}

function setup(tr, babel) {
  if (babel === 'babel') {
    const presets = [];
    if (presetEnv) {
      presets.push([
        presetEnv.default,
        {targets: {node: true}},
      ]);
    }
    presets.push(
      /\.tsx?$/.test(tr) ?
        require('@babel/preset-typescript').default :
        require('@babel/preset-flow').default
    );

    require('@babel/register')({
      configFile: false,
      babelrc: false,
      presets,
      plugins: [
        require('@babel/plugin-transform-class-properties').default,
        require('@babel/plugin-transform-nullish-coalescing-operator').default,
        require('@babel/plugin-transform-optional-chaining').default,
        require('@babel/plugin-transform-modules-commonjs').default,
        require('@babel/plugin-transform-private-methods').default,
      ],
      extensions: [...DEFAULT_EXTENSIONS, '.ts', '.tsx'],
      ignore: [
        /@babel\/parser/,
        /\/flow-parser\//,
        /\/recast\//,
        /\/ast-types\//,
      ],
    });
  }

  const mod = require(tr);
  transform = typeof mod.default === 'function' ?
    mod.default :
    mod;
  if (mod.parser) {
    parserFromTransform = typeof mod.parser === 'string' ?
      getParser(mod.parser) :
      mod.parser;
  }
}

function free() {
  notify({action: 'free'});
}

function updateStatus(status, file, msg) {
  msg = msg ? file + ' ' + msg : file;
  notify({action: 'status', status: status, msg: msg});
}

function report(file, msg) {
  notify({action: 'report', file, msg});
}

function empty() {}

function stats(name, quantity) {
  quantity = typeof quantity !== 'number' ? 1 : quantity;
  notify({action: 'update', name: name, quantity: quantity});
}

function trimStackTrace(trace) {
  if (!trace) {
    return '';
  }
  const lines = trace.split('\n');
  const result = [];
  const self = __filename;
  lines.every(function(line) {
    if (line.indexOf(self) === -1) {
      result.push(line);
      return true;
    }
  });
  return result.join('\n');
}

function run(data) {
  const files = data.files;
  const options = data.options || {};
  if (!files.length) {
    finish();
    return;
  }
  async.each(
    files,
    function(file, callback) {
      fs.readFile(file, async function(err, source) {
        if (err) {
          updateStatus('error', file, 'File error: ' + err);
          callback();
          return;
        }
        source = source.toString();
        try {
          const jscodeshiftApi = prepareJscodeshift(options);
          const out = await transform(
            {
              path: file,
              source: source,
            },
            {
              j: jscodeshiftApi,
              jscodeshift: jscodeshiftApi,
              stats: options.dry ? stats : empty,
              report: msg => report(file, msg),
            },
            options
          );
          if (!out || out === source) {
            updateStatus(out ? 'nochange' : 'skip', file);
            callback();
            return;
          }
          if (options.print) {
            console.error(out); // print to stderr so it doesn't break JSON protocol?
            // Original uses console.log (stdout). Rust runner uses stdout for IPC.
            // Emit a special print message; Rust will write it. For parity with
            // dry/print development, write transformed file content to stderr fd
            // is wrong. Instead notify print and also write directly to fd 3 or
            // use a side channel.
            // Best effort: write to the real console via process.stderr is visible
            // but original goes to stdout. We'll write a raw line marker.
            // Actually: the original Worker console.log goes to worker's stdout
            // which is not the IPC channel in child_process.fork (fork uses IPC).
            // With fork, console.log still goes to inherited stdout!
            // So print output goes to the parent's stdout mixed with runner output.
            // Here stdout is IPC. Use the original stdout by writing to fd of
            // /dev/tty or duplicate. Simplest: write print output as a notify
            // and have Rust print it — but that adds a prefix.
            // Use process.stderr.write is wrong.
            // Open inherited: node keeps fd 1 as pipe. We can write to the
            // controlling terminal, but tests capture stdout.
            // Protocol: send {action:'print', content: out} and Rust prints it.
            notify({action: 'print', content: out});
          }
          if (!options.dry) {
            writeFileAtomic(file, out, function(err) {
              if (err) {
                updateStatus('error', file, 'File writer error: ' + err);
              } else {
                updateStatus('ok', file);
              }
              callback();
            });
          } else {
            updateStatus('ok', file);
            callback();
          }
        } catch(err) {
          updateStatus(
            'error',
            file,
            'Transformation error ('+ String(err.message || err).replace(/\n/g, ' ') + ')\n' + trimStackTrace(err.stack)
          );
          callback();
        }
      });
    },
    function(err) {
      if (err) {
        updateStatus('error', '', 'This should never be shown!');
      }
      free();
    }
  );
}

// Args: transform path, babel|no-babel
const transformPath = process.argv[2];
const babelFlag = process.argv[3] || 'babel';

if (!transformPath) {
  process.stderr.write('transform-host: missing transform path\n');
  process.exit(1);
}

setup(path.resolve(transformPath), babelFlag);

const rl = readline.createInterface({ input: process.stdin, crlfDelay: Infinity });
rl.on('line', (line) => {
  line = line.trim();
  if (!line) return;
  try {
    const data = JSON.parse(line);
    run(data);
  } catch (e) {
    updateStatus('error', '', 'Invalid worker message: ' + e.message);
    free();
  }
});

rl.on('close', () => {
  // stdin closed
  setImmediate(() => process.exit(0));
});
"}

