'use strict';

const { spawnSync } = require('child_process');
const fs = require('fs');
const path = require('path');

const packageRoot = path.resolve(__dirname, '..');
process.env.JSCODESHIFT_ROOT = packageRoot;

function findBinary() {
  const names = process.platform === 'win32' ? ['jscodeshift.exe'] : ['jscodeshift'];
  const candidates = [];

  if (process.env.JSCODESHIFT_BIN) {
    candidates.push(process.env.JSCODESHIFT_BIN);
  }

  // Build output locations
  const targetDir = process.env.CARGO_TARGET_DIR || path.join(packageRoot, 'rust', 'target');
  for (const name of names) {
    candidates.push(path.join(targetDir, 'release', name));
    candidates.push(path.join(targetDir, 'debug', name));
    candidates.push(path.join(packageRoot, 'bin', name));
    candidates.push(path.join(packageRoot, 'target', 'release', name));
    candidates.push(path.join(packageRoot, 'target', 'debug', name));
  }

  // Workspace-level cargo target (OpenHands env)
  if (process.env.CARGO_TARGET_DIR) {
    for (const name of names) {
      candidates.push(path.join(process.env.CARGO_TARGET_DIR, 'release', name));
      candidates.push(path.join(process.env.CARGO_TARGET_DIR, 'debug', name));
    }
  }
  // Common workspace path
  candidates.push('/workspace/.cargo-target/release/jscodeshift');
  candidates.push('/workspace/.cargo-target/debug/jscodeshift');

  for (const c of candidates) {
    try {
      if (c && fs.existsSync(c)) {
        return c;
      }
    } catch (_) {}
  }
  return null;
}

const bin = findBinary();
if (!bin) {
  process.stderr.write(
    'jscodeshift: native binary not found. Run app-setup/build.sh (or cargo build --release -p jscodeshift) first.\n'
  );
  process.exit(1);
}

const result = spawnSync(bin, process.argv.slice(2), {
  stdio: 'inherit',
  env: process.env,
});

if (result.error) {
  process.stderr.write('jscodeshift: failed to launch binary: ' + result.error.message + '\n');
  process.exit(1);
}

process.exit(result.status == null ? 1 : result.status);
