// then walk up looking for package.json named jscodeshift.
function findPackageRoot() {
  if (process.env.JSCODESHIFT_ROOT) {
    return path.resolve(process.env.JSCODESHIFT_ROOT);
  }
  let dir = path.resolve(__dirname, '..');
  for (let i = 0; i < 6; i++) {
    try {
      const pkg = require(path.join(dir, 'package.json'));
      if (pkg && pkg.name === 'jscodeshift') {
        return dir;
      }
    } catch (_) {}
    const parent = path.dirname(dir);
    if (parent === dir) break;
    dir = parent;
  }
  // Fallback: parent of bridge/ (codebase/bridge -> codebase)
  return path.resolve(__dirname, '..');
}

const PACKAGE_ROOT = findPackageRoot();

const getParser = require(path.join(PACKAGE_ROOT, 'src', 'getParser'));
const jscodeshift = require(path.join(PACKAGE_ROOT, 'src', 'core'));"}

