    let mut cmd = Command::new("node");
    cmd.arg(bridge)
        .arg(transform)
        .arg(babel_arg)
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::inherit())
        .env("JSCODESHIFT_ROOT", package_root);
    // Prefer resolving modules from the package root
    if let Ok(node_path) = std::env::var("NODE_PATH") {
        let combined = format!(
