            package_root.join("node_modules").display(),
            if cfg!(windows) { ";" } else { ":" },
            node_path
        );
        cmd.env("NODE_PATH", combined);
    } else {
        cmd.env(
            "NODE_PATH",
            package_root.join("node_modules").display().to_string(),
